/** The example scenarios in examples/, shared by the runner script and test/examples.test.ts. */

export interface ExampleRun {
  /** Label shown in output and test names. */
  name: string;
  /** Folder under examples/. */
  folder: string;
  /** APK/AAB file in the example folder, generated by scripts/make-example-apks.ts (git-ignored). */
  apk?: string;
  exitCode: 0 | 1 | 2;
  /** Every finding id expected, as "severity:id", sorted. Empty for exit code 2 (no report). */
  findings: string[];
}

