/** CLI arguments for an example, relative to the repository root. */
export function exampleArgs(example: ExampleRun): string[] {
  return [
    `examples/${example.folder}`,
    ...(example.apk ? ['--apk', `examples/${example.folder}/${example.apk}`] : []),
    '--offline',
    '--cache-dir',
    'examples/registry-snapshot',
  ];
}
